import express, { type Request, Response, NextFunction } from "express";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    throw err;
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 5000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = parseInt(process.env.PORT || '5000', 10);
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

server/routes.ts.content:
import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { insertAssessmentSchema, assessmentResponsesSchema, dimensionScoresSchema } from "@shared/schema";
import { z } from "zod";

function calculateOverallScore(scores: any): number {
  const values = Object.values(scores) as number[];
  const average = values.reduce((sum, score) => sum + score, 0) / values.length;
  return Math.round(average * 20); // Convert to 100-point scale
}

function calculateDimensionScores(responses: any): any {
  const scores: any = {};

  // Group questions by dimension - map actual question IDs to dimensions
  const dimensionMappings = [
    { name: 'technologyInfrastructure', patterns: ['tech-', 'technologyInfrastructure'] },
    { name: 'dataQuality', patterns: ['data-', 'dataQuality'] },
    { name: 'teamLiteracy', patterns: ['team-', 'teamLiteracy'] },
    { name: 'systemIntegration', patterns: ['system-', 'integration-', 'systemIntegration'] },
    { name: 'budget', patterns: ['budget-', 'resource-', 'budget', 'budgetResources'] },
    { name: 'dataSecurity', patterns: ['security-', 'privacy-', 'dataSecurity', 'security', 'securityPrivacy'] }
  ];

  dimensionMappings.forEach((dimensionMapping) => {
    let totalScore = 0;
    let questionCount = 0;

    // Look through all responses and match by pattern
    Object.keys(responses).forEach(questionId => {
      const matchesPattern = dimensionMapping.patterns.some(pattern => 
        questionId.toLowerCase().includes(pattern.toLowerCase()) || 
        questionId.startsWith(pattern)
      );

      if (matchesPattern) {
        totalScore += responses[questionId];
        questionCount++;
      }
    });

    // Only include dimension in scores if we have questions for it
    if (questionCount > 0) {
      scores[dimensionMapping.name] = totalScore / questionCount;
    }
  });

  // Add a fallback to ensure we have valid scores
  if (Object.keys(scores).length === 0) {
    console.warn('No dimension scores calculated, using fallback logic');
    // Simple fallback: average all responses and assign to each dimension
    const allResponses = Object.values(responses) as number[];
    const averageScore = allResponses.length > 0 ? 
      allResponses.reduce((sum, score) => sum + score, 0) / allResponses.length : 3;

    scores.technologyInfrastructure = averageScore;
    scores.dataQuality = averageScore;
    scores.teamLiteracy = averageScore;
    scores.systemIntegration = averageScore;
    scores.budget = averageScore;
    scores.dataSecurity = averageScore;
  }

  return scores;
}

export async function registerRoutes(app: Express): Promise<Server> {

  // Submit assessment
  app.post("/api/assessments", async (req, res) => {
    try {
      const requestSchema = z.object({
        organizationName: z.string().min(1).optional(),
        contactEmail: z.string().email().optional(),
        industry: z.string().min(1),
        responses: assessmentResponsesSchema,
      });

      const { organizationName, contactEmail, industry, responses } = requestSchema.parse(req.body);

      // Calculate dimension scores
      const scores = calculateDimensionScores(responses);

      // Calculate overall score
      const overallScore = calculateOverallScore(scores);

      const assessment = await storage.createAssessment({
        organizationName,
        contactEmail,
        industry,
        responses,
        scores,
        overallScore,
      });

      res.json(assessment);
    } catch (error) {
      console.error("Error creating assessment:", error);
      res.status(400).json({ 
        message: error instanceof Error ? error.message : "Invalid request data" 
      });
    }
  });

  // Get assessment by ID
  app.get("/api/assessments/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const assessment = await storage.getAssessment(id);

      if (!assessment) {
        return res.status(404).json({ message: "Assessment not found" });
      }

      res.json(assessment);
    } catch (error) {
      console.error("Error fetching assessment:", error);
      res.status(500).json({ message: "Internal server error" });
    }
  });

  // Get all assessments
  app.get("/api/assessments", async (req, res) => {
    try {
      const assessments = await storage.getAllAssessments();
      res.json(assessments);
    } catch (error) {
      console.error("Error fetching assessments:", error);
      res.status(500).json({ message: "Internal server error" });
    }
  });

  // Email request endpoint - store email requests and send assessment reports via email
  app.post("/api/assessment-email-requests", async (req, res) => {
    try {
      // Check for Brevo API key
      if (!process.env.BREVO_API_KEY) {
        return res.status(503).json({ 
          message: "Email service not configured. Please add BREVO_API_KEY to environment variables." 
        });
      }

      const emailRequestSchema = z.object({
        assessmentId: z.string(),
        email: z.string().email(),
        contactConsent: z.boolean().default(false),
      });

      const { assessmentId, email, contactConsent } = emailRequestSchema.parse(req.body);

      // Verify the assessment exists
      const assessment = await storage.getAssessment(assessmentId);
      if (!assessment) {
        return res.status(404).json({ message: "Assessment not found" });
      }

      // Store the email request in database
      const emailRequest = await storage.createEmailRequest({
        assessmentId,
        email,
        contactConsent: contactConsent ? 'true' : 'false',
        emailSent: 'false'
      });

      // Generate email HTML (escape HTML in organizationName)
      const { sendEmail, generateAssessmentEmailHTML } = await import('./services/email');
      const safeOrgName = (assessment.organizationName || 'Your Organization')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
      const htmlContent = generateAssessmentEmailHTML(assessment, safeOrgName);

      // Try to generate PDF report (optional - may fail in some environments)
      let pdfBase64: string | undefined;
      try {
        const { generateAssessmentPDF } = await import('./services/pdf-generator');
        const pdfBuffer = await generateAssessmentPDF(assessment);
        pdfBase64 = pdfBuffer.toString('base64');
        console.log('PDF generated successfully');
      } catch (pdfError) {
        console.warn('PDF generation failed, sending email without attachment:', pdfError instanceof Error ? pdfError.message : 'Unknown error');
      }

      // Send email with or without PDF attachment
      await sendEmail({
        to: email,
        subject: `Your AI Readiness Assessment Report - ${assessment.organizationName || 'Results'}`,
        htmlContent,
        pdfBase64,
        pdfFilename: `AI-Readiness-Report-${(assessment.organizationName || 'Report').replace(/[^a-zA-Z0-9]/g, '-')}.pdf`
      });

      // Update email request status
      await storage.updateEmailRequestSentStatus(emailRequest.id, new Date());

      console.log(`Email sent successfully to ${email} for assessment ${assessmentId}, Contact consent: ${contactConsent}`);

      // Return success
      res.status(200).json({ message: "Email sent successfully with PDF report" });
    } catch (error) {
      console.error("Error processing email request:", error);
      res.status(500).json({ 
        message: error instanceof Error ? error.message : "Failed to send email" 
      });
    }
  });



  const httpServer = createServer(app);
  return httpServer;
}

server/storage.ts.content:
import { type Assessment, type InsertAssessment, assessments, type EmailRequest, type InsertEmailRequest, emailRequests } from "@shared/schema";
import { randomUUID } from "crypto";
import { db } from "./db";
import { eq } from "drizzle-orm";

export interface IStorage {
  getAssessment(id: string): Promise<Assessment | undefined>;
  createAssessment(assessment: InsertAssessment): Promise<Assessment>;
  getAllAssessments(): Promise<Assessment[]>;
  createEmailRequest(emailRequest: InsertEmailRequest): Promise<EmailRequest>;
  getEmailRequestsByAssessment(assessmentId: string): Promise<EmailRequest[]>;
  getAllEmailRequests(): Promise<EmailRequest[]>;
  updateEmailRequestSentStatus(id: string, sentAt: Date): Promise<void>;
}

export class MemStorage implements IStorage {
  private assessments: Map<string, Assessment>;
  private emailRequests: Map<string, EmailRequest>;

  constructor() {
    this.assessments = new Map();
    this.emailRequests = new Map();
  }

  async getAssessment(id: string): Promise<Assessment | undefined> {
    return this.assessments.get(id);
  }

  async createAssessment(insertAssessment: InsertAssessment): Promise<Assessment> {
    const id = randomUUID();
    const assessment: Assessment = {
      ...insertAssessment,
      id,
      createdAt: new Date(),
    };
    this.assessments.set(id, assessment);
    return assessment;
  }

  async getAllAssessments(): Promise<Assessment[]> {
    return Array.from(this.assessments.values());
  }

  async createEmailRequest(insertEmailRequest: InsertEmailRequest): Promise<EmailRequest> {
    const id = randomUUID();
    const emailRequest: EmailRequest = {
      id,
      assessmentId: insertEmailRequest.assessmentId,
      email: insertEmailRequest.email,
      contactConsent: insertEmailRequest.contactConsent || 'false',
      emailSent: insertEmailRequest.emailSent || 'false',
      sentAt: insertEmailRequest.sentAt || null,
      createdAt: new Date(),
    };
    this.emailRequests.set(id, emailRequest);
    return emailRequest;
  }

  async getEmailRequestsByAssessment(assessmentId: string): Promise<EmailRequest[]> {
    return Array.from(this.emailRequests.values()).filter(
      req => req.assessmentId === assessmentId
    );
  }

  async getAllEmailRequests(): Promise<EmailRequest[]> {
    return Array.from(this.emailRequests.values());
  }

  async updateEmailRequestSentStatus(id: string, sentAt: Date): Promise<void> {
    const emailRequest = this.emailRequests.get(id);
    if (emailRequest) {
      emailRequest.emailSent = 'true';
      emailRequest.sentAt = sentAt;
      this.emailRequests.set(id, emailRequest);
    }
  }
}

export class DatabaseStorage implements IStorage {
  async getAssessment(id: string): Promise<Assessment | undefined> {
    const [assessment] = await db.select().from(assessments).where(eq(assessments.id, id));
    return assessment || undefined;
  }

  async createAssessment(insertAssessment: InsertAssessment): Promise<Assessment> {
    const [assessment] = await db
      .insert(assessments)
      .values(insertAssessment)
      .returning();
    return assessment;
  }

  async getAllAssessments(): Promise<Assessment[]> {
    return await db.select().from(assessments);
  }

  async createEmailRequest(insertEmailRequest: InsertEmailRequest): Promise<EmailRequest> {
    const [emailRequest] = await db
      .insert(emailRequests)
      .values(insertEmailRequest)
      .returning();
    return emailRequest;
  }

  async getEmailRequestsByAssessment(assessmentId: string): Promise<EmailRequest[]> {
    return await db.select().from(emailRequests).where(eq(emailRequests.assessmentId, assessmentId));
  }

  async getAllEmailRequests(): Promise<EmailRequest[]> {
    return await db.select().from(emailRequests);
  }

  async updateEmailRequestSentStatus(id: string, sentAt: Date): Promise<void> {
    await db
      .update(emailRequests)
      .set({ emailSent: 'true', sentAt })
      .where(eq(emailRequests.id, id));
  }
}

// Use in-memory storage for development, database for production
const useDatabase = process.env.NODE_ENV === 'production' && process.env.USE_MEMORY_STORAGE !== 'true';

console.log(`[Storage] Using ${useDatabase ? 'PostgreSQL Database' : 'In-Memory'} storage`);

export const storage = useDatabase ? new DatabaseStorage() : new MemStorage();

